// Flatten Fortinet's {kind: {bucket_ms: [event, ...]}} payload into one item
// holding every event as a row for attack_events. Dedupe happens in SQL
// (event_key = md5 of the raw event), so overlapping polls are harmless.
const payload = $input.first().json;
const rows = [];

for (const [kind, buckets] of Object.entries(payload)) {
  if (!buckets || typeof buckets !== 'object' || Array.isArray(buckets)) continue;
  for (const [bucketMs, events] of Object.entries(buckets)) {
    if (!Array.isArray(events)) continue;
    for (const e of events) {
      rows.push({
        event_ms: Number(bucketMs) || e.redis_ms,
        kind,
        signature: e.vuln_name ?? e.virus_name ?? e.name ?? null,
        category: e.profile_type ?? null,
        severity: e.severity ?? null,
        outbreak_id: e.outbreak_id ?? null,
        outbreak_tags: Array.isArray(e.outbreak_alert) ? e.outbreak_alert : [],
        src_country: e.src_country ?? null,
        src_city: e.src_city ?? null,
        src_lat: e.src_lat ?? null,
        src_lon: e.src_long ?? null,
        dst_country: e.dest_country ?? null,
        dst_city: e.dest_city ?? null,
        dst_lat: e.dest_lat ?? null,
        dst_lon: e.dest_long ?? null,
        hits: e.count ?? 1,
        raw: e,
      });
    }
  }
}

return rows.length ? [{ json: { rows } }] : [];
